"""Root-cause diagnostic (campaign v1.5.2, lane D, group G-test-graphify-ci; run by lane A). Test-side only.

1. generated_ignore (graphify_ci.py:44-72) marks a file generated when any of its
   first comment lines matches GENERATED_HEADER (graphify_ci.py:37-40); the third
   alternative has all prefixes optional, so a bare "generated by"/"generated from"
   inside a handwritten comment matches. Logs the matching line and alternative,
   and runs a corrected copy (Go's standard marker only) on the corpus and on the
   stringer control.
2. failed() (graphify_ci.py:149-153) upserts without the current-head check that
   check() performs (graphify_ci.py:140-143). Runs a corrected copy that performs
   that check first.
"""
import os
from pathlib import Path
import re
import sys
import unittest
from unittest import mock

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import graphify_ci  # noqa: E402

REPO = HERE.parent.parent
CORPUS = REPO / "testing/cypher/differential/corpus.go"
GO_STANDARD = re.compile(r"^// Code generated .* DO NOT EDIT\.$")


class RCAGeneratedHeader(unittest.TestCase):
    def test_rca_matching_line(self):
        for index, line in enumerate(CORPUS.read_text(encoding="utf-8").splitlines()[:60]):
            match = graphify_ci.GENERATED_HEADER.search(line.strip())
            if match:
                print(f"RCA_GRAPHIFY corpus.go line {index + 1}: {line.strip()!r} matched {match.group(0)!r}")
                break
        for text in ("// Code generated by stringer; DO NOT EDIT.", line.strip()):
            print(f"RCA_GRAPHIFY corrected (Go standard marker) {text!r} -> generated={bool(GO_STANDARD.match(text))}")


class RCAFailedPath(unittest.TestCase):
    def run_failed(self, function):
        calls = []
        head_b, base_c, head_a = "b" * 40, "c" * 40, "a" * 40

        class StandIn:
            def __init__(self, base, repo, token):
                self.repo = "org/repo"

            def request(self, method, path, body=None):
                calls.append((method, path))
                if method == "GET" and path == "/repos/org/repo/pulls/17":
                    return {"state": "open", "head": {"sha": head_b}, "base": {"sha": base_c}}
                if method == "GET" and path.startswith("/repos/org/repo/issues/17/comments"):
                    return [{"id": 123, "user": {"login": "github-actions[bot]"}, "body": graphify_ci.MARKER + "\nreport for head " + head_b}]
                return None

        env = {"GITHUB_API_URL": "https://example.test", "GITHUB_REPOSITORY": "org/repo", "GITHUB_TOKEN": "fixture",
               "GITHUB_SERVER_URL": "https://example.test", "GITHUB_RUN_ID": "100", "PR_NUMBER": "17",
               "PR_HEAD_SHA": head_a, "PR_BASE_SHA": base_c}
        with mock.patch.dict(os.environ, env), mock.patch.object(graphify_ci, "API", StandIn):
            function()
        return calls

    def test_rca_failed_requests(self):
        print("RCA_GRAPHIFY failed() as shipped:", self.run_failed(graphify_ci.failed))

        def corrected():
            api = graphify_ci.API(os.environ["GITHUB_API_URL"], os.environ["GITHUB_REPOSITORY"], os.environ["GITHUB_TOKEN"])
            number = int(os.environ["PR_NUMBER"])
            current = api.request("GET", f"/repos/{api.repo}/pulls/{number}")
            if current.get("state") != "open" or current["head"]["sha"] != os.environ["PR_HEAD_SHA"]:
                return
            graphify_ci.failed()

        print("RCA_GRAPHIFY failed() with check()'s current-head guard first:", self.run_failed(corrected))


if __name__ == "__main__":
    unittest.main()
